Posting
post sends the comment and shows the result. The body is JSON, but labelled text/plain: a JSON content type would make the browser send a CORS preflight request first, which Apps Script web apps cannot answer, and the post would be blocked. Apps Script follows a redirect to return its reply, which fetch follows automatically. Any { ok: false } reply is shown to the reader as the relay’s own message. On success, the thanks wording is shown with its {issue} placeholder made into a link to the new issue.

_extensions/issue-comments/issue-comments.js, lines 203–243
async function post(name, comment) {
  const payload = {
    name,
    comment,
    quote: current.quote,
    section: current.section,
    anchor: current.anchor,
    page: location.origin + location.pathname,
    passcode: passInput.value,
    website: trap.value,
  };
  goBtn.disabled = true;
  backBtn.disabled = true;
  status.textContent = say("posting");
  status.className = "ic-status";
  try {
    // text/plain avoids a CORS preflight, which Apps Script cannot answer.
    const res = await fetch(cfg.endpoint, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify(payload),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "The comment was not posted.");
    setStage("done");
    status.className = "ic-status ic-ok";
    const issueText = say("issue-link", { number: String(data.number) });
    status.replaceChildren(...fill(T.thanks, {
      issue: data.url
        ? el("a", { href: data.url, target: "_blank", rel: "noopener", text: issueText })
        : issueText,
    }));
    window.getSelection().removeAllRanges();
  } catch (err) {
    status.textContent = err.message || "Something went wrong. Please try again.";
    status.className = "ic-status ic-error";
    goBtn.disabled = false;
  } finally {
    backBtn.disabled = false;
  }
}

